function validate(input) {
  const [{ Calls = [] }] = input;
  const seen = new Set();
  for (const [caller, recipient, time, city] of Calls) {
    if (caller === null || recipient === null) return 'caller_id and recipient_id cannot be null.';
    if (typeof time !== 'string' || !/^\d{4}-\d{2}-\d{2} ([01]\d|2[0-3]):[0-5]\d:[0-5]\d$/.test(time)) return `call_time ${time} is not a datetime.`;
    if (city === null) return 'city cannot be null.';
    const key = `${caller}|${recipient}|${time}`;
    if (seen.has(key)) return `The call ${caller} -> ${recipient} at ${time} appears twice.`;
    seen.add(key);
  }
  return null;
}

