function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const two = n => String(n).padStart(2, '0');
  const small = size === 'small';
  const cities = small ? ['Houston', 'New York', 'Boston'] : ['Houston', 'New York', 'Boston', 'Miami', 'Denver', 'Austin', 'Seattle', 'Chicago', 'Phoenix', 'Dallas'];
  // Small cases use a few hours so counts tie; large ones spread over the whole day.
  const hours = small ? [0, 13, 14, 22, 23] : Array.from({ length: 24 }, (_, h) => h);
  const count = small ? Math.floor(rand() * 9) : 2000;
  const Calls = [], seen = new Set();
  while (Calls.length < count) {
    const caller = 1 + Math.floor(rand() * (small ? 6 : 200));
    let recipient = 1 + Math.floor(rand() * (small ? 6 : 200));
    if (recipient === caller) recipient = caller + 1;
    const time = `2021-08-${two(1 + Math.floor(rand() * (small ? 3 : 28)))} ${two(pick(hours))}:${two(Math.floor(rand() * 60))}:${two(Math.floor(rand() * 60))}`;
    const key = `${caller}|${recipient}|${time}`;
    if (seen.has(key)) continue;
    seen.add(key);
    Calls.push([caller, recipient, time, pick(cities)]);
  }
  return [{ Calls }];
}
